mapper.select:
SELECT FROM wms_batch b JOIN wms_material m ON m.id = b.material_id
b.material_id = #{q.materialId}
AND (m.code LIKE CONCAT('%', #{q.keyword}, '%') OR m.name LIKE CONCAT('%', #{q.keyword}, '%'))
AND b.batch_no LIKE CONCAT('%', #{q.batchNo}, '%') AND b.expiry_date <= #{q.expireBefore}
AND EXISTS (SELECT 1 FROM wms_stock s WHERE s.material_id = b.material_id AND s.batch_no = b.batch_no AND s.qty > 0)
ORDER BY b.id DESC
